import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题"},"headers":[],"relativePath":"api/faq.md","filePath":"api/faq.md","lastUpdated":1795698978000}'),i={name:"api/faq.md"};function l(s,a,n,d,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h2 id="返回-401-如何排查" tabindex="-1">返回 401，如何排查？ <a class="header-anchor" href="#返回-401-如何排查" aria-label="Permalink to &quot;返回 401，如何排查？&quot;">​</a></h2><p>请依次检查：</p><ol><li>请求头名称是否为 <code>X-API-Key</code>。</li><li>API Key 是否完整，以 <code>rpk_</code> 开头，没有多余的空格、换行或引号。</li><li>API Key 是否与控制台 <strong>API Key</strong> 页面显示的一致。</li><li>环境变量是否正确加载，可以先打印 Key 的前几位确认，但不要打印完整 Key。</li></ol><p>详见 <a href="./authentication/api-key.html">认证方式</a>。</p><h2 id="资源在控制台可以看到-为什么-api-返回-404" tabindex="-1">资源在控制台可以看到，为什么 API 返回 404？ <a class="header-anchor" href="#资源在控制台可以看到-为什么-api-返回-404" aria-label="Permalink to &quot;资源在控制台可以看到，为什么 API 返回 404？&quot;">​</a></h2><p>常见原因：</p><ul><li><strong>接口与资源类型不匹配</strong>：例如将独立服务器的服务 ID 用于 <code>/vps/{id}</code>。请使用与产品对应的接口，或先通过 <code>GET /services</code> 确认服务类型。</li><li><strong>API Key 属于其他账户</strong>：API 只能访问 API Key 所属账户的资源。</li></ul><h2 id="操作返回-204-但资源状态没有变化" tabindex="-1">操作返回 204，但资源状态没有变化？ <a class="header-anchor" href="#操作返回-204-但资源状态没有变化" aria-label="Permalink to &quot;操作返回 204，但资源状态没有变化？&quot;">​</a></h2><p><code>204</code> 表示指令已下发，操作需要一定时间完成。请等待片刻后查询资源详情。如果长时间没有变化，请登录控制台查看，或提交工单。详见 <a href="./general/async-operations.html">异步操作</a>。</p><h2 id="返回-409-是什么原因" tabindex="-1">返回 409 是什么原因？ <a class="header-anchor" href="#返回-409-是什么原因" aria-label="Permalink to &quot;返回 409 是什么原因？&quot;">​</a></h2><p>资源当前的状态不允许执行该操作，例如服务已暂停，或弹性 IP 已绑定到其他实例。请根据 <code>error_message</code> 和资源当前状态处理。详见 <a href="./general/status-codes.html#_409-状态冲突">HTTP 状态码</a>。</p><h2 id="返回-429-怎么办" tabindex="-1">返回 429 怎么办？ <a class="header-anchor" href="#返回-429-怎么办" aria-label="Permalink to &quot;返回 429 怎么办？&quot;">​</a></h2><p>请求频率超过了限制。请降低请求频率，等待后重试。详见 <a href="./general/rate-limits.html">请求频率限制</a>。</p>',13)])])}const f=e(i,[["render",l]]);export{_ as __pageData,f as default};
